def transform(grid):
    h,w=len(grid),len(grid[0])
    # Diagonal seed lines run along r+c=constant. Their colors in the
    # spatial sequence define the repeating diagonal-band word.
    bands={}
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v:
                bands.setdefault(r+c,set()).add(v)
    if len(bands)<2:
        return [row[:] for row in grid]
    # Each diagonal seed specifies the color of its nearest parallel bands.
    seeds=[]
    for k in sorted(bands):
        if len(bands[k]) == 1:
            seeds.append((k, next(iter(bands[k]))))
    if not seeds:
        return [row[:] for row in grid]
    return [[min(seeds, key=lambda item: (abs(r+c-item[0]), item[0]))[1]
             for c in range(w)] for r in range(h)]", "exit_code": 0, "error": null}

